75	    ///
76	    /// # Errors
77	    ///
78	    /// [`VcsError::CheckpointHeld`] when `name` already exists, so two runs never share one; a failed git command
79	    /// otherwise.
80	    pub fn create_checkpoint(&self, name: &str, facts: &CheckpointFacts, date: &str) -> Result<CommitSha, VcsError> {
