100	        if !output.success() {
101	            return Err(if output.stderr.contains("already exists") {
102	                VcsError::CheckpointHeld { name: name.to_string() }
103	            } else {
104	                git_failed(&args, self.root(), &output.stderr)
105	            });
106	        }
107	        Ok(commit)
108	    }
