115	    /// Whether `path` (relative to this root) is on disk as `rev` recorded it, compared as Git compares: through its
116	    /// line-ending and attribute filters, so a checkout with CRLF endings matches the blob it was written from. Absent
117	    /// on both sides matches.
118	    pub fn path_matches_at(&self, rev: &str, path: &Path) -> Result<bool, VcsError> {
