123	    pub fn blob_hash_at(&self, rev: &str, path: &Path) -> Result<Option<String>, VcsError> {
124	        if !self.path_exists_at(rev, path)? {
125	            return Ok(None);
126	        }
127	        let spec = format!("{rev}:./{}", path.display());
128	        self.git_stdout(&["rev-parse", &spec]).map(Some)
129	    }
130	
131	    /// The object id Git would give the file at `path` (relative to this root) as it is on disk now, through its
132	    /// line-ending and attribute filters, or `None` when it is absent. Two ids are equal exactly when Git would
133	    /// store the same content.
134	    pub fn file_hash(&self, path: &Path) -> Result<Option<String>, VcsError> {
135	        let full = self.root().join(path);
136	        if !full.is_file() {
137	            return Ok(None);
138	        }
139	        let name = path.to_string_lossy();
140	        let file = full.to_string_lossy();
141	        self.git_stdout(&["hash-object", "--path", &name, &file]).map(Some)
142	    }
143	
144	    /// Checks the checkpoint at `name` out at `dir` (which must not exist) with `HEAD` on the commit the run started
145	    /// from, so history reads (commit inference) see the real commits and not the checkpoint's own. The files and the
146	    /// index stay as the checkpoint recorded them.
147	    pub fn add_checkpoint_worktree(&self, name: &str, dir: &Path, head: &str) -> Result<(), VcsError> {
148	        let dir_text = dir.to_string_lossy();
149	        self.git_stdout(&["worktree", "add", "--detach", "--quiet", &dir_text, name])?;
150	        let args = ["reset", "--quiet", "--soft", head];
151	        let output = self.runner().run("git", &args, dir)?;
152	        if !output.success() {
153	            return Err(git_failed(&args, dir, &output.stderr));
154	        }
155	        Ok(())
156	    }
157	
158	    /// Files under this root that exist now but not in `rev`: untracked ones and ones added to the index, relative to
159	    /// this root.
160	    pub fn created_since(&self, rev: &str) -> Result<Vec<std::path::PathBuf>, VcsError> {
161	        let mut created = self.untracked_files()?;
162	        let added = self.git_stdout(&["diff", "--name-only", "--relative", "--diff-filter=A", rev, "--", "."])?;
163	        created.extend(added.lines().map(std::path::PathBuf::from));
164	        created.sort();
165	        created.dedup();
166	        Ok(created)
167	    }
168	
169	    /// This root's path inside the repository (empty at the top), so the same directory can be found in a worktree.
170	    pub fn root_prefix(&self) -> Result<std::path::PathBuf, VcsError> {
171	        self.git_stdout(&["rev-parse", "--show-prefix"])
172	            .map(std::path::PathBuf::from)
173	    }
174	
175	    /// Untracked, not ignored files under this root, relative to it.
176	    pub fn untracked_files(&self) -> Result<Vec<std::path::PathBuf>, VcsError> {
177	        let listed = self.git_stdout(&["ls-files", "--others", "--exclude-standard", "--", "."])?;
178	        Ok(listed.lines().map(std::path::PathBuf::from).collect())
179	    }
180	
181	    /// The files under `dir` (relative to this root) in `rev`'s tree, relative to this root.
182	    pub fn files_at(&self, rev: &str, dir: &Path) -> Result<Vec<std::path::PathBuf>, VcsError> {
183	        let dir = dir.to_string_lossy();
184	        let listed = self.git_stdout(&["ls-tree", "-r", "--name-only", rev, "--", &dir])?;
185	        Ok(listed.lines().map(std::path::PathBuf::from).collect())
186	    }
187	
188	    /// Removes a worktree [`Self::add_checkpoint_worktree`] added.
189	    pub fn remove_worktree(&self, dir: &Path) -> Result<(), VcsError> {
190	        let dir = dir.to_string_lossy();
191	        self.git_stdout(&["worktree", "remove", "--force", &dir]).map(drop)
192	    }
193	
194	    /// An unsigned commit of `tree` with fixed identity: it records state and is never pushed, so the user's signing
195	    /// key and identity play no part.
196	    fn internal_commit(&self, tree: &str, parents: &[&str], message: &str) -> Result<CommitSha, VcsError> {
197	        let mut args = vec![
198	            "-c",
199	            "user.name=Callisto",
200	            "-c",
201	            "user.email=callisto@localhost",
202	            "commit-tree",
203	            "--no-gpg-sign",
204	            tree,
205	        ];
206	        for parent in parents {
207	            args.extend(["-p", parent]);
208	        }
209	        args.extend(["-m", message]);
210	        let sha = self.git_stdout(&args)?;
211	        CommitSha::parse(&sha).map_err(|e| VcsError::InvalidCommitSha {
212	            context: "in `git commit-tree` output".to_string(),
213	            message: e.to_string(),
214	        })
215	    }
216	
217	    fn git_stdout(&self, args: &[&str]) -> Result<String, VcsError> {
218	        self.git_stdout_env(args, &[])
219	    }
220	
221	    fn git_stdout_env(&self, args: &[&str], env: &[(&str, &str)]) -> Result<String, VcsError> {
222	        let output = self.runner().run_with_env("git", args, self.root(), env)?;
223	        if !output.success() {
224	            return Err(git_failed(args, self.root(), &output.stderr));
225	        }
226	        Ok(output.stdout_trimmed().to_string())
227	    }
228	}
229	
230	fn git_failed(args: &[&str], root: &Path, stderr: &str) -> VcsError {
231	    VcsError::Git(format!(
232	        "`git {}` failed in `{}`: {}",
233	        args.join(" "),
234	        root.display(),
235	        stderr.trim()
236	    ))
237	}
