//! Proves, before the first write, that every file a version plan touches can be written and committed, so a bad
//! target stops the run with nothing changed instead of leaving earlier manifests rewritten.

use std::collections::BTreeSet;
use std::path::{Component, Path, PathBuf};

use callisto_model::{ApplyPermit, CommandError, CommandRunner};

use super::ApplyOptions;
use crate::cascade::DepWriteTarget;
use crate::error::GraphError;
use crate::plan::{VersionPlan, VersionWriteTarget};

/// What a plan does to a path, which decides what must hold for it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Target {
    /// A manifest the plan edits: it must exist as a readable regular file and its directory must take a new file.
    Existing,
    /// A file the plan may create or replace, such as a changelog or `pre.json`.
    Creatable,
    /// A file the plan deletes: only the path itself is checked.
    Removed,
}

/// Every path `plan` writes or deletes under `opts`, once each.
fn targets(plan: &VersionPlan, opts: &ApplyOptions) -> BTreeSet<(PathBuf, Target)> {
    let mut targets = BTreeSet::new();
    for bump in &plan.bumps {
        for write in &bump.writes {
            let path = match write {
                VersionWriteTarget::Manifest(path) => path,
                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => root_manifest,
            };
            targets.insert((path.clone(), Target::Existing));
        }
    }
    for rewrite in &plan.rewrites {
        let path = match &rewrite.key.target {
            DepWriteTarget::Manifest(path) => path,
            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => root_manifest,
        };
        targets.insert((path.clone(), Target::Existing));
    }
    targets.extend(
        plan.platform_writes
            .iter()
            .map(|write| (write.manifest.clone(), Target::Existing)),
    );
    targets.extend(
        plan.optional_dep_updates
            .iter()
            .map(|update| (update.manifest.clone(), Target::Existing)),
    );
    if !opts.transient {
        targets.extend(
            plan.changelog_writes
                .iter()
                .map(|write| (write.changelog_path.clone(), Target::Creatable)),
        );
        targets.extend(
            plan.consumed_changesets
                .iter()
                .map(|path| (path.clone(), Target::Removed)),
        );
        if plan.pre_state_update.is_some() {
            targets.insert((plan.pre_json_path.clone(), Target::Creatable));
        } else if let Some(path) = &plan.delete_pre_json {
            targets.insert((path.clone(), Target::Removed));
        }
    }
    targets
}

/// Every path `plan` writes, creates or deletes in a run that records changelogs and consumes changesets.
pub(super) fn written_paths(plan: &VersionPlan) -> BTreeSet<PathBuf> {
    targets(plan, &ApplyOptions::default())
        .into_iter()
        .map(|(path, _)| path)
        .collect()
}

/// Fails with every target that cannot be written, before anything is.
///
/// # Errors
///
/// [`GraphError::ApplyPreflight`] naming each unwritable path and why.
pub(super) fn check<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
    runner: &R,
) -> Result<(), GraphError> {
    let targets = targets(plan, opts);
    let mut problems: Vec<String> = targets
        .iter()
        .filter_map(|(path, target)| {
            problem(root, path, *target, permit).map(|reason| format!("`{}`: {reason}", path.display()))
        })
        .collect();
    if !opts.transient {
        let staged: Vec<PathBuf> = targets
            .iter()
            .filter(|(_, target)| *target != Target::Removed)
            .map(|(path, _)| path.clone())
            .collect();
        problems.extend(ignored_paths(runner, root, &staged)?.into_iter().map(|path| {
            format!(
                "`{}`: is ignored by a .gitignore, so Git would not stage it",
                path.display()
            )
        }));
    }
    if problems.is_empty() {
        Ok(())
    } else {
        Err(GraphError::ApplyPreflight { problems })
    }
}

/// The paths of `paths` that a `.gitignore` ignores and Git does not already track, which `git add` refuses.
///
/// # Errors
///
/// `git check-ignore` could not run or failed (anything but "some ignored" and "none ignored").
pub(super) fn ignored_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    paths: &[PathBuf],
) -> Result<BTreeSet<PathBuf>, GraphError> {
    if paths.is_empty() {
        return Ok(BTreeSet::new());
    }
    // One quiet run answers the usual "none ignored"; only when something is does each path get asked, so no output
    // needs parsing (git quotes unusual names).
    if !any_ignored(runner, root, paths)? {
        return Ok(BTreeSet::new());
    }
    let mut ignored = BTreeSet::new();
    for path in paths {
    let mut deferred_deletions = Vec::new();

    let ctx = OpenContext::for_workspace_root(root)?;
    preflight::check(root, plan, opts, permit, runner)?;
    let active_ecosystems = active_ecosystems(plan);
    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
        touched_cargo_workspaces(root, plan)?
    } else {
        BTreeSet::new()
    };
    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
    let classification = classify_manifest_writes(plan);

    for step in write_steps(plan, &classification) {
        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
    }

    if !opts.transient {
        for cl in &plan.changelog_writes {
            let rendered = crate::changelog::render_section(&cl.input)?;
            crate::changelog::prepend(
                root,
                &cl.changelog_path,
                &cl.input.package.display_name(),
                &rendered,
                permit,
            )?;
            modified_paths.push(cl.changelog_path.clone());
        }

        for cs_path in &plan.consumed_changesets {
            deferred_deletions.push(cs_path.clone());
        }

        if let Some(ref pre_state) = plan.pre_state_update {
            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
            let rel_pre_path = plan.pre_json_path.clone();
            let pre_path = root.join(&rel_pre_path);
            let text = match &plan.pre_json_original_text {
                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
                None => callisto_model::format::write_pre_json(pre_state),
            };
            callisto_model::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
                path: rel_pre_path.clone(),
                message: e.to_string(),
            })?;
            modified_paths.push(rel_pre_path);
        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
            deferred_deletions.push(rel_pre_path.clone());
        }
    }

    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
    if opts.refresh_lockfiles {
        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
        if !refresh_results.is_empty() {
            outcome.lockfile_refresh_results = Some(refresh_results);
        }
    }

    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
    for p in lockfile_candidate_paths(&lockfile_dirs, &cargo_workspaces) {
        if path_exists(root, &p)? && !modified_paths.contains(&p) {
            lockfile_paths.push(p.clone());
            modified_paths.push(p);
        }
    }

    // A lockfile that a .gitignore ignores (a library's `Cargo.lock`, say) is not meant to be committed: refreshed on disk,
    // never staged. Anything else the plan stages was checked before the first write.
    if !opts.transient {
        let ignored = preflight::ignored_paths(runner, root, &lockfile_paths)?;
        modified_paths.retain(|path| !ignored.contains(path));
    }

    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
        // Stage all written release state before consuming its inputs. If a refresh or add fails,
        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
        // still identifies the interrupted run.
        let mut existing = Vec::new();
        let mut deleted = Vec::new();
        for path in &modified_paths {
            if path_exists(root, path)? {
                existing.push(path);
            } else {
                deleted.push(path);
            }
        }

        if !existing.is_empty() {
            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
        }

        if !deleted.is_empty() {
            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
        }

        if !deferred_deletions.is_empty() {
            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;

            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
            for path in &deferred_deletions {
                match fs::remove_file(root.join(path)) {
                    Ok(()) => {}
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                    Err(e) => {
                        return Err(GraphError::ApplyIo {
                            path: path.clone(),
                            message: e.to_string(),
                        })
                    }
                }
            }
            modified_paths.extend(deferred_deletions.iter().cloned());
        }

        outcome.staged = modified_paths;
    }

    Ok(outcome)
}

/// Every lockfile a run of `plan` may refresh or create, whether or not it exists: the known lockfile names beside each
/// npm and Python workspace the plan wrote into, and each Cargo workspace's `Cargo.lock`. Apply refreshes and stages
/// these; abort removes the ones the run created.
pub fn lockfile_candidates(root: &Path, plan: &VersionPlan) -> Result<Vec<PathBuf>, GraphError> {
    let active = active_ecosystems(plan);
    let cargo_workspaces = if active.contains(&Ecosystem::Cargo) {
        touched_cargo_workspaces(root, plan)?
    } else {
        BTreeSet::new()
    };
    Ok(lockfile_candidate_paths(
        &lockfile_dirs(root, plan, &active)?,
        &cargo_workspaces,
    ))
}

fn lockfile_candidate_paths(dirs: &LockfileDirs, cargo_workspaces: &BTreeSet<PathBuf>) -> Vec<PathBuf> {
    let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
        dirs.iter()
            .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
            .collect()
    };
    beside(&dirs.npm, &NPM_LOCKFILES)
        .into_iter()
        .chain(beside(&dirs.pypi, &PYPI_LOCKFILES))
        .chain(cargo_workspaces.iter().map(|workspace| cargo_lockfile(workspace)))

